import pandas as pd, numpy as np
rows=[]
for i in range(1,12):
    try:
        df=pd.read_csv(globals()[f"experiment_{i}_csv"])
        d={"exp":i,"n":len(df)}
        for c in df.columns:
            if df[c].dtype!=object:
                d[c]=df[c].mean()
        rows.append(d)
    except Exception as e:
        print(i,"err",e)
agg=pd.DataFrame(rows)
cols=[c for c in agg.columns if c not in ("exp","n")]
print(agg[["exp"]+cols].round(2).to_string())

